def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0 if hp > 4 else 42.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    low_hp_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('hp', 0) <= 5:
            low_hp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days >= 1:
        urgency += 0.35

    urgency += 0.45 * supply_pressure
    urgency += 0.08 * desperate_count

    if highest_prev >= 140:
        market_mode = 'burnout'
    elif highest_prev >= 115:
        market_mode = 'hot'
    elif highest_prev > 0:
        market_mode = 'normal'
    else:
        market_mode = 'unknown'

    if market_mode == 'burnout':
        if urgency >= 1.0:
            bid = min(0.92 * DAILY_SALARY, highest_prev + 1.0)
        else:
            bid = 0.34 * DAILY_SALARY
    elif market_mode == 'hot':
        if urgency >= 1.0:
            bid = min(0.88 * DAILY_SALARY, avg_prev * 0.72)
        elif supply >= 21 and hp >= 6:
            bid = 0.30 * DAILY_SALARY
        else:
            bid = max(0.44 * DAILY_SALARY, avg_prev * 0.52)
    elif market_mode == 'normal':
        if urgency >= 1.0:
            bid = max(0.70 * DAILY_SALARY, highest_prev + 2.0)
        else:
            bid = max(0.46 * DAILY_SALARY, avg_prev * 0.78 + 1.0)
    else:
        if urgency >= 1.0:
            bid = 0.78 * DAILY_SALARY
        elif supply >= 21:
            bid = 0.32 * DAILY_SALARY
        else:
            bid = 0.50 * DAILY_SALARY

    if rich_count >= 2 and supply <= 17:
        bid += 6.0
    if low_hp_count >= 2 and hp >= 6 and supply >= 20:
        bid -= 5.0

    if day >= 8:
        bid += 5.0 * urgency
    if day <= 2 and hp >= 7 and supply >= 20:
        bid -= 4.0

    reserve_target = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve_target = min(budget, days_left * 18.0)
    spend_cap = max(0.0, budget - reserve_target * 0.25)
    if urgency >= 1.0:
        spend_cap = budget

    bid = max(0.0, bid)
    bid = min(bid, spend_cap)
    bid = min(bid, budget)

    if hp <= 2:
        bid = max(bid, min(budget, 60.0))
    elif hp <= 4 and supply <= 18:
        bid = max(bid, min(budget, 48.0))

    return float(round(max(0.0, min(budget, bid)), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append(opp)

    # React to yesterday bids (immediate trace only)
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base aggressiveness from supply level: higher supply => bid slightly more to outcompete
    # but cap to avoid overspending.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If my hp is low, spend to avoid death.
    if hp <= 2.0:
        target = DAILY_SALARY * 0.95
    elif hp <= 4.0 or no_water_days >= 2:
        target = DAILY_SALARY * 0.75
    else:
        target = DAILY_SALARY * (0.45 + 0.25 * supply_ratio)

    # If opponents were bidding very high yesterday, raise bid to match the arms race.
    if prev_bids:
        highest_prev = max(prev_bids)
        # Alex/Cindy were around 120-124; treat >=0.85*DAILY_SALARY as high pressure.
        if highest_prev >= DAILY_SALARY * 0.85:
            if hp > 3.0:
                target = max(target, DAILY_SALARY * 0.65)
            else:
                target = max(target, DAILY_SALARY * 0.9)
        else:
            # If they weren't extreme, bid a bit above yesterday typical to secure water.
            avg_prev = sum(prev_bids) / float(len(prev_bids))
            target = max(target, min(DAILY_SALARY * 0.8, avg_prev + 5.0))

    # Convert target to a final bid under budget.
    # Never bid more than budget or a reasonable fraction of budget.
    max_affordable = budget
    # Keep a reserve so we don't bankrupt early.
    reserve_factor = 0.15 if hp > 3.0 else 0.05
    bid_cap = max_affordable * (1.0 - reserve_factor)

    final_bid = min(bid_cap, target)

    # Ensure non-negative and at least a small amount if budget allows.
    if final_bid < 0.0:
        final_bid = 0.0
    if final_bid == 0.0 and budget > 0.0:
        final_bid = min(budget, DAILY_SALARY * 0.1)

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    is_desperate = my_status['no_water_days'] >= 1 or my_status['hp'] <= 2
    is_late_game = day_context['day'] >= EPISODE_DAYS - 2

    if is_desperate:
        return min(my_status['budget'], DAILY_SALARY * 1.02)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.85

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        target_bid = highest_prev_bid + 2.0

        if my_status['hp'] > 5:
            bid = min(DAILY_SALARY * 0.95, target_bid)
        else:
            bid = min(DAILY_SALARY * 0.98, target_bid)

        bid = max(bid, average_prev_bid * 0.95)
        bid = max(bid, DAILY_SALARY * 0.8)

        if is_late_game and my_status['budget'] > DAILY_SALARY * 2:
            bid = max(bid, DAILY_SALARY * 1.0)
            bid = min(bid, my_status['budget'])

        return min(my_status['budget'], bid)

    return min(my_status['budget'], base_bid)
